const vert = `attribute vec3 aPosition;
  attribute vec3 aNormal;
  attribute vec2 aTexCoord;

  uniform mat4 uModelViewMatrix;
  uniform mat4 uProjectionMatrix;
  uniform mat3 uNormalMatrix;

  varying highp vec2 vVertTexCoord;

  void main(void) {
    vec4 positionVec4 = vec4(aPosition, 1.0);
    gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
    vVertTexCoord = aTexCoord;
  }
`
const frag = `precision mediump float;
  varying highp vec2 vVertTexCoord;

  uniform sampler2D uImg;
  uniform sampler2D uDepth;
  uniform vec2 uSize;
  uniform float uIntensity;
  uniform int uNumSamples;
  uniform float uTargetZ;
  uniform float uNear;
  uniform float uFar;

  const int MAX_NUM_SAMPLES = 50;

  float rand(vec2 co){
    return fract(sin(dot(co.xy ,vec2(12.9898,78.233))) * 43758.5453);
  }

  float depthToZ(float depth) {
    float depthNormalized = 2.0 * depth - 1.0;
    return 2.0 * uNear * uFar / (uFar + uNear - depthNormalized * (uFar - uNear));
  }

  float calcBlur(float z, float pixelScale) {
    return clamp(abs(z - uTargetZ), 0.0, 0.5*pixelScale);
  }

  vec4 addFog(vec4 color, float z) {
    vec4 fogColor = vec4(0.05, 0.05, 0.05, 1.0);
    vec4 withFog = mix(color, fogColor, clamp(z / 1200. - 0.2, 0., 1.));
    return withFog;
  }

  float getBrightness(vec4 color) {
    float b = color.z;
    b = smoothstep(0., 1., b);
    b = smoothstep(0., 1., b);
    b = pow(b, 0.8);
    b = clamp(b * 1.35, 0., 1.);
    return b;
  }

  void main() {
    float pixelScale = max(uSize.x, uSize.y);
    float total = 1.0;
    float origZ = depthToZ(texture2D(uDepth, vVertTexCoord).x);
    vec4 color = addFog(texture2D(uImg, vVertTexCoord), origZ);
    float blurAmt = calcBlur(origZ, pixelScale);
    for (int i = 0; i < MAX_NUM_SAMPLES; i++) {
      if (i >= uNumSamples) break;
      float t = (float(i + 1) / float(uNumSamples));
      float angle = (t*4.0) * ${2 * Math.PI};
      float radius = 1.0 - (t*t*t); // Sample more on the outer edge
      angle += 1.*rand(gl_FragCoord.xy);
      vec2 offset = (vec2(cos(angle),sin(angle)) * radius * uIntensity * blurAmt)/pixelScale;
      float z = depthToZ(texture2D(uDepth, vVertTexCoord + offset).x);
      float sampleBlur = calcBlur(z, pixelScale);

      //float weight = float(z >= origZ);
      float weight = float((z >= origZ) || (sampleBlur >= blurAmt*radius + 5.));
      //vec4 sample = addFog(texture2D(uImg, vVertTexCoord + offset), z);
			vec4 sample = texture2D(uImg, vVertTexCoord + offset);
      color += weight * sample;
      total += weight;
    }
    color /= total;
		gl_FragColor = color;
    //float brightness = getBrightness(color);
    //gl_FragColor = vec4(brightness, brightness, brightness, 1.0);
  }
  `

// === Tab: BezierPath ===
const SAMPLE_SPACING = 2

class BezierSegment {
  constructor(A, B, C, D) {
    this.A = A
    this.B = B
    this.C = C
    this.D = D
  }

  tangentAtParameter(parameter) {
    const t = Math.max(0, Math.min(1, parameter)) // clamp to [0, 1]
    const adjustedT = 1 - t
    const x =
      3 * this.D.x * Math.pow(t, 2) -
      3 * this.C.x * Math.pow(t, 2) +
      6 * this.C.x * adjustedT * t -
      6 * this.B.x * adjustedT * t +
      3 * this.B.x * Math.pow(adjustedT, 2) -
      3 * this.A.x * Math.pow(adjustedT, 2)

    const y =
      3 * this.D.y * Math.pow(t, 2) -
      3 * this.C.y * Math.pow(t, 2) +
      6 * this.C.y * adjustedT * t -
      6 * this.B.y * adjustedT * t +
      3 * this.B.y * Math.pow(adjustedT, 2) -
      3 * this.A.y * Math.pow(adjustedT, 2)

    const z =
      3 * this.D.z * Math.pow(t, 2) -
      3 * this.C.z * Math.pow(t, 2) +
      6 * this.C.z * adjustedT * t -
      6 * this.B.z * adjustedT * t +
      3 * this.B.z * Math.pow(adjustedT, 2) -
      3 * this.A.z * Math.pow(adjustedT, 2)

    return { x, y, z }
  }

  pointAtParameter(parameter) {
    var t = Math.max(0, Math.min(1, parameter)) // clamp to [0, 1]
    return {
      x:
        Math.pow(1 - t, 3) * this.A.x +
        3 * Math.pow(1 - t, 2) * t * this.B.x +
        3 * (1 - t) * Math.pow(t, 2) * this.C.x +
        Math.pow(t, 3) * this.D.x,
      y:
        Math.pow(1 - t, 3) * this.A.y +
        3 * Math.pow(1 - t, 2) * t * this.B.y +
        3 * (1 - t) * Math.pow(t, 2) * this.C.y +
        Math.pow(t, 3) * this.D.y,
      z:
        Math.pow(1 - t, 3) * this.A.z +
        3 * Math.pow(1 - t, 2) * t * this.B.z +
        3 * (1 - t) * Math.pow(t, 2) * this.C.z +
        Math.pow(t, 3) * this.D.z,
    }
  }

  getTotalLength() {
    if (this._totalLength === undefined) {
      const initialSamples = Math.max(
        10,
        Math.ceil(
          (Math.hypot(this.B.x - this.A.x, this.B.y - this.A.y, this.B.z - this.A.z) +
            Math.hypot(this.C.x - this.B.x, this.C.y - this.B.y, this.C.z - this.A.z) +
            Math.hypot(this.D.x - this.C.x, this.D.y - this.C.y, this.D.z - this.C.z)) /
            SAMPLE_SPACING
        )
      )
      const pts = _.times(initialSamples).map((i) =>
        this.pointAtParameter(i / (initialSamples - 1))
      )
      let total = 0
      for (let i = 1; i < pts.length; i++) {
        total += Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y, pts[i].z - pts[i - 1].z)
      }
      this._totalLength = total
    }

    return this._totalLength
  }
}

class BezierPath {
  constructor(segments) {
    this.segments = segments
    this.samples = []

    const segmentLengths = segments.map((s) => s.getTotalLength())
    const segmentOffsets = [0]
    for (let i = 1; i < segmentLengths.length; i++) {
      segmentOffsets.push(segmentOffsets[i - 1] + segmentLengths[i - 1])
    }
    this._totalLength =
      segmentOffsets[segmentOffsets.length - 1] +
      segmentLengths[segmentLengths.length - 1]

    const numSamples = Math.max(
      10,
      Math.ceil(this._totalLength / SAMPLE_SPACING)
    )
    const stepSize = 1 / numSamples / 10

    const avgDist = this._totalLength / numSamples
    this.samples.push({
      dist: 0,
      pt: this.segments[0].A,
      tan: this.segments[0].tangentAtParameter(0),
      segIdx: 0,
      t: 0,
    })
    segments.forEach((seg, segIdx) => {
      const numSegSamples = Math.max(
        1,
        Math.round(numSamples * (seg.getTotalLength() / this._totalLength))
      )

      // Include one extra point at the end at t = 1
      const ts = _.times(numSegSamples + 1).map((i) => i / numSegSamples)
      var pts = ts.map((t) => seg.pointAtParameter(t))
      let dists
      for (let it = 0; it < 4; it++) {
        dists = _.times(numSegSamples).map((i) =>
          Math.hypot(pts[i + 1].x - pts[i].x, pts[i + 1].y - pts[i].y, pts[i + 1].z - pts[i].z)
        )
        const distErrors = dists.map((d) => d - avgDist)
        let offset = 0
        for (let i = 1; i < ts.length - 1; i++) {
          // Shift this t value to get closer to the target length
          offset += distErrors[i - 1]
          ts[i] -= stepSize * offset

          // Sample the point at the new t value
          pts[i] = seg.pointAtParameter(ts[i])
        }
      }

      let lastOffset = 0
      pts.slice(1).forEach((pt, i) => {
        lastOffset += dists[i]
        this.samples.push({
          dist: segmentOffsets[segIdx] + lastOffset,
          pt,
          tan: this.segments[segIdx].tangentAtParameter(ts[i + 1]),
          segIdx,
          t: ts[i + 1],
        })
      })
    })
  }

  getTotalLength() {
    return this._totalLength
  }

  findClosestSampleIdx(dist) {
    // Binary search to find the sample with the closest dist
    let lo = 0
    let hi = this.samples.length - 1

    while (lo < hi) {
      const mid = Math.floor((lo + hi) / 2)

      if (this.samples[mid].dist > dist) {
        hi = mid - 1
      } else if (this.samples[mid].dist < dist) {
        lo = mid + 1
      } else {
        return mid
      }
    }

    return Math.max(
      0,
      Math.min(this.samples.length - 1, Math.floor((lo + hi) / 2)),
    )
  }

  getPointAtLength(length, approximate) {
    if (length <= 0) return this.samples[0].pt
    if (length >= this._totalLength)
      return this.samples[this.samples.length - 1].pt

    const idxA = this.findClosestSampleIdx(length)
    const idxB =
      this.samples[idxA].dist < length
        ? Math.min(idxA + 1, this.samples.length - 1)
        : Math.max(0, idxA - 1)
    const mix =
      (length - this.samples[idxA].dist) /
      (this.samples[idxB].dist - this.samples[idxA].dist)

    if (
      approximate ||
      this.samples[idxA].segIdx !== this.samples[idxB].segIdx
    ) {
      // We have a set of evenly spaced samples that are close enough together
      // that we can probably just linearly interpolate between them without
      // too much loss of quality
      var x =
        (1 - mix) * this.samples[idxA].pt.x + mix * this.samples[idxB].pt.x
      var y =
        (1 - mix) * this.samples[idxA].pt.y + mix * this.samples[idxB].pt.y
      var z =
        (1 - mix) * this.samples[idxA].pt.z + mix * this.samples[idxB].pt.z
      return { x, y, z }
    } else {
      // Find the t value between the two samples. This is not EXACTLY the point
      // at the target distance along the path, but it's so close that it
      // is effectively the same
      const segment = this.segments[this.samples[idxA].segIdx]
      var t = (1 - mix) * this.samples[idxA].t + mix * this.samples[idxB].t
      return segment.pointAtParameter(t)
    }
  }

  getTangentAtLength(length, approximate) {
    if (length <= 0) return this.samples[0].tan
    if (length >= this._totalLength)
      return this.samples[this.samples.length - 1].tan

    var idxA = this.findClosestSampleIdx(length)
    var idxB =
      this.samples[idxA].dist < length
        ? Math.min(idxA + 1, this.samples.length - 1)
        : Math.max(0, idxA - 1)
    var mix =
      (length - this.samples[idxA].dist) /
      (this.samples[idxB].dist - this.samples[idxA].dist)

    if (
      approximate ||
      this.samples[idxA].segIdx !== this.samples[idxB].segIdx
    ) {
      // We have a set of evenly spaced samples that are close enough together
      // that we can probably just linearly interpolate between them without
      // too much loss of quality
      var x =
        (1 - mix) * this.samples[idxA].tan.x + mix * this.samples[idxB].tan.x
      var y =
        (1 - mix) * this.samples[idxA].tan.y + mix * this.samples[idxB].tan.y
      var z =
        (1 - mix) * this.samples[idxA].tan.z + mix * this.samples[idxB].tan.z
      return { x, y, z }
    } else {
      // Find the t value between the two samples. This is not EXACTLY the point
      // at the target distance along the path, but it's so close that it
      // is effectively the same
      var segment = this.segments[this.samples[idxA].segIdx]
      var t = (1 - mix) * this.samples[idxA].t + mix * this.samples[idxB].t
      return segment.tangentAtParameter(t)
    }
  }
}


const createBezierPath = (points) => {
  const segments = []
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1]
    const curr = points[i]
    segments.push(
      new BezierSegment(
        prev.pt,
        prev.right || prev.pt,
        curr.left || curr.pt,
        curr.pt,
      ),
    )
  }
  return new BezierPath(segments)
}

// === Tab: genLine ===
const genBezier = function() {
	noiseSeed(random(1000))
	const points = [{
		pt: createVector(
			random(-0.25, 0.25)*width,
			random(-0.25, 0.25)*height,
			random(-0.25, 0.25)*height
		)
	}]
	const numPoints = 30
	const spacing = 200
	const noiseDist = 400
	while (points.length < numPoints) {
		const pt = points[points.length-1]
			.pt
			.copy()
			.add(
				createVector(
					map(noise(points.length*noiseDist, 0*noiseDist), 0, 1, -spacing, spacing),
					map(noise(points.length*noiseDist, 1*noiseDist), 0, 1, -spacing, spacing),
					map(noise(points.length*noiseDist, 2*noiseDist), 0, 1, -spacing, spacing),
				)
			)
		points.push({ pt })
	}

	// Recenter the points
	const avg = points
		.map((p) => p.pt)
		.reduce((acc, next) => acc.copy().add(next))
		.mult(1 / points.length)
	points.forEach((p) => {
		p.pt.sub(avg)
	})

	// Add bezier tangent control points to make it smooth
	for (let i = 0; i < points.length; i++) {
		var prev = points[(i - 1 + points.length) % points.length]
		var curr = points[i]
		const next = points[(i + 1) % points.length]
		const tangent = next.pt.copy().sub(prev.pt).mult(1/3)
		curr.left = curr.pt.copy().sub(tangent)
		curr.right = curr.pt.copy().add(tangent)
	}

	// Make it join up
	//points.push(points[0])

	return createBezierPath(points)
}

const bezierToPipeGeom = function(bezier) {
	return new p5.Geometry(1, 1, function() {
    this.gid = 'pipe'
		const pointSpacing = 3
		var numPoints = ceil(bezier.getTotalLength() / pointSpacing)
		const numCirclePoints = 12

		const centers = []
		const tangents = []
		const normals = []
		const biNormals = []
		for (let i = 0; i < numPoints; i++) {
			const frac = i / (numPoints - 1)
			const u = frac
			const distance = frac * bezier.getTotalLength()
			const center = bezier.getPointAtLength(distance)
			var tangent = bezier.getTangentAtLength(distance)

			const centerVec = createVector(center.x, center.y, center.z)
			const tangentVec = createVector(tangent.x, tangent.y, tangent.z).normalize()
			centers.push(centerVec)
			tangents.push(tangentVec)
		}

		for (let i = 0; i < numPoints; i++) {
			var tangentVec = tangents[i]
			let prevTangent, nextTangent
			if (i < 1) {
				prevTangent = tangentVec
				const nextFrac = (i+0.01)/(numPoints - 1)
				const nextTangentRaw = bezier.getTangentAtLength(nextFrac * bezier.getTotalLength())
				nextTangent = createVector(nextTangentRaw.x, nextTangentRaw.y, nextTangentRaw.z).normalize()
			} else {
				const prevFrac = (i-0.01)/(numPoints - 1)
				const prevTangentRaw = bezier.getTangentAtLength(prevFrac * bezier.getTotalLength())
				prevTangent = createVector(prevTangentRaw.x, prevTangentRaw.y, prevTangentRaw.z).normalize()
				nextTangent = tangentVec
			}
			const normalVec = nextTangent.copy().sub(prevTangent)
			normals.push(normalVec)
		}

		for (let i = 0; i < numPoints; i++) {
			if (normals[i].magSq() < 0.9) {
				if (i === 0) {
					normals[i] = createVector(0, 1, 0).cross(tangents[i]).normalize()
				} else {
					normals[i] = normals[i - 1].copy()
				}
				normals[i].normalize()
			} else {
				normals[i].normalize()
			}
		}

		normals.forEach((normal, i) => {
			const biNormalVec = tangents[i].cross(normal).normalize()
			biNormals.push(biNormalVec)
			const biBiNormal = biNormalVec.cross(tangents[i]).normalize()
			normal.set(biBiNormal.x, biBiNormal.y, biBiNormal.z)
